        {
            if(p->pAudioStreamInfo[i].pCodecSpecificData != NULL &&
               p->pAudioStreamInfo[i].nCodecSpecificDataLen > 0)
            {
                free(p->pAudioStreamInfo[i].pCodecSpecificData);
                p->pAudioStreamInfo[i].pCodecSpecificData = NULL;
                p->pAudioStreamInfo[i].nCodecSpecificDataLen = 0;
            }
